---
import Layout from '../layouts/Layout.astro';
import {
  successMessage,
  trimValues,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from '../lib/contact';

export const prerender = false;

let values: ContactValues = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';

if (Astro.request.method === 'POST') {
  let data: FormData | undefined;
  try {
    data = await Astro.request.formData();
  } catch {
    data = undefined;
  }
  const field = (key: string) => {
    const value = data?.get(key);
    return typeof value === 'string' ? value : '';
  };
  values = { name: field('name'), email: field('email'), message: field('message') };
  errors = validateContact(values);
  const ok = Object.keys(errors).length === 0;
  if (ok) success = successMessage(values.name);

  if (Astro.request.headers.get('accept')?.includes('application/json')) {
    return Response.json(
      ok ? { ok, message: success } : { ok, errors },
      { status: ok ? 200 : 400 },
    );
  }

  if (ok) values = { name: '', email: '', message: '' };
  else Astro.response.status = 400;
}

const trimmed = trimValues(values);
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p id="contact-success" class="success" role="status" hidden={!success}>{success}</p>
  <form method="post" action="/contact" novalidate id="contact-form">
    <div class="field">
      <label for="name">Name</label>
      <input
        type="text"
        id="name"
        name="name"
        value={trimmed.name}
        aria-describedby="name-error"
        aria-invalid={errors.name ? 'true' : undefined}
      />
      <p class="error" id="name-error" hidden={!errors.name}>{errors.name}</p>
    </div>
    <div class="field">
      <label for="email">Email</label>
      <input
        type="email"
        id="email"
        name="email"
        value={trimmed.email}
        aria-describedby="email-error"
        aria-invalid={errors.email ? 'true' : undefined}
      />
      <p class="error" id="email-error" hidden={!errors.email}>{errors.email}</p>
    </div>
    <div class="field">
      <label for="message">Message</label>
      <textarea
        id="message"
        name="message"
        rows="6"
        aria-describedby="message-error"
        aria-invalid={errors.message ? 'true' : undefined}>{trimmed.message}</textarea>
      <p class="error" id="message-error" hidden={!errors.message}>{errors.message}</p>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<script>
  import { successMessage, validateContact, type ContactField } from '../lib/contact';

  const form = document.querySelector<HTMLFormElement>('#contact-form');
  const status = document.querySelector<HTMLElement>('#contact-success');
  const fields: ContactField[] = ['name', 'email', 'message'];

  function showErrors(errors: Partial<Record<ContactField, string>>) {
    for (const field of fields) {
      const input = document.getElementById(field);
      const error = document.getElementById(`${field}-error`);
      const message = errors[field] ?? '';
      if (error) {
        error.textContent = message;
        error.hidden = !message;
      }
      if (message) input?.setAttribute('aria-invalid', 'true');
      else input?.removeAttribute('aria-invalid');
    }
  }

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (status) {
      status.hidden = true;
      status.textContent = '';
    }
    const data = new FormData(form);
    const values = {
      name: String(data.get('name') ?? ''),
      email: String(data.get('email') ?? ''),
      message: String(data.get('message') ?? ''),
    };
    const errors = validateContact(values);
    showErrors(errors);
    if (Object.keys(errors).length > 0) return;

    const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]');
    if (submit) submit.disabled = true;
    try {
      const response = await fetch(form.action, {
        method: 'POST',
        body: data,
        headers: { Accept: 'application/json' },
      });
      const result = await response.json();
      if (result.ok) {
        form.reset();
        if (status) {
          status.textContent = result.message ?? successMessage(values.name);
          status.hidden = false;
        }
      } else {
        showErrors(result.errors ?? {});
      }
    } catch {
      if (status) {
        status.textContent = 'Something went wrong. Please try again.';
        status.hidden = false;
      }
    } finally {
      if (submit) submit.disabled = false;
    }
  });
</script>

<style>
  .field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin-bottom: 1rem;
  }
  input,
  textarea {
    font: inherit;
    padding: 0.4rem;
    max-width: 30rem;
  }
  .error {
    color: #b00020;
    margin: 0;
  }
  .success {
    color: #116329;
    font-weight: 600;
  }
  button {
    font: inherit;
    padding: 0.4rem 1rem;
    cursor: pointer;
  }
</style>
EOF
