log('btn after reload', await fav.textContent());
await page.goto(B + '/books');
log('fav items', await page.locator('ul[aria-label="Books"] li:has(strong:visible)').allTextContents());
await page.goto(B + '/books/dracula');
await page.locator('#favorite').click();
